"""Artifact import and deterministic unit-map construction."""

from __future__ import annotations

import ast
import json
import re
from dataclasses import replace
from typing import Iterable

from .content_log import ContentLog
from .hashing import sha256_text, stable_id
from .records import AddressMap, Artifact, ArtifactReviewStatus, ArtifactState, ArtifactUnit


def import_artifact(log: ContentLog, *, kind: str, path_or_name: str, text: str) -> Artifact:
    blob = log.append_blob(text, media_type="text/plain", name=path_or_name)
    artifact_id = stable_id("artifact", {"kind": kind, "path": path_or_name})
    return Artifact(
        artifact_id=artifact_id,
        kind=kind,
        path_or_name=path_or_name,
        version_hash=blob.sha256,
        blob_ref=blob.blob_ref,
        text=text,
    )


def build_address_map(artifact: Artifact) -> AddressMap:
    if artifact.kind in {"python", "code", "source"} or artifact.path_or_name.endswith(".py"):
        units = _unitize_python(artifact)
    elif artifact.kind in {"markdown", "document", "md"} or artifact.path_or_name.endswith((".md", ".markdown")):
        units = _unitize_markdown(artifact)
    elif artifact.kind in {"html", "web_page", "web"} or artifact.path_or_name.endswith((".html", ".htm")):
        units = _unitize_html(artifact)
    elif artifact.kind in {"json", "world_map", "ceiba_world_map", "surface_map"} or artifact.path_or_name.endswith(".json"):
        units = _unitize_json(artifact)
    elif artifact.kind in {"log", "verifier", "transcript"}:
        units = _unitize_log(artifact)
    else:
        units = _unitize_text(artifact)

    map_id = stable_id(
        "map",
        {
            "artifact_id": artifact.artifact_id,
            "version_hash": artifact.version_hash,
            "addresses": sorted(units),
        },
    )
    return AddressMap(map_id=map_id, artifact_id=artifact.artifact_id, version_hash=artifact.version_hash, units=units)


def artifact_state_from_map(artifact: Artifact, address_map: AddressMap) -> ArtifactState:
    exact_units = [
        unit
        for unit in address_map.units.values()
        if unit.unit_kind
        in {
            "file",
            "section",
            "error",
            "function",
            "class",
            "web_page",
            "ui_element",
            "link",
            "heading",
            "json",
            "json_value",
            "world_map",
            "surface",
            "semantic_block",
            "image_region",
        }
    ]
    exact_units.sort(key=lambda unit: (unit.parent_address is None, unit.start_line, unit.address))
    exact_refs = [unit.exact_ref for unit in exact_units]
    return ArtifactState(
        artifact_id=artifact.artifact_id,
        kind=artifact.kind,
        path_or_name=artifact.path_or_name,
        version_hash=artifact.version_hash,
        address_map_ref=address_map.map_id,
        review_status=ArtifactReviewStatus.MAPPED,
        exact_window_refs=exact_refs[:8],
    )


def resolve_address(address_maps: dict[str, AddressMap], address_or_ref: str) -> ArtifactUnit | None:
    for address_map in address_maps.values():
        for unit in address_map.units.values():
            if address_or_ref in {unit.address, unit.unit_id, unit.exact_ref}:
                return unit
    return None


def mark_artifact_stale(state: ArtifactState) -> ArtifactState:
    return replace(state, review_status=ArtifactReviewStatus.STALE)


def exact_text_for_unit(artifact: Artifact, unit: ArtifactUnit) -> str:
    if unit.inline_text is not None:
        return unit.inline_text
    lines = artifact.text.splitlines()
    return "\n".join(lines[unit.start_line - 1 : unit.end_line])


def _unitize_python(artifact: Artifact) -> dict[str, ArtifactUnit]:
    lines = artifact.text.splitlines()
    root = _make_unit(artifact, "file", "file", artifact.path_or_name, 1, max(len(lines), 1), None)
    units = {root.address: root}
    child_addresses: list[str] = []

    try:
        tree = ast.parse(artifact.text)
    except SyntaxError:
        return _with_children(units, root.address, child_addresses)

    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            kind = "class" if isinstance(node, ast.ClassDef) else "function"
            start = getattr(node, "lineno", 1)
            end = getattr(node, "end_lineno", start)
            address = f"{kind}:{node.name}"
            unit = _make_unit(artifact, address, kind, node.name, start, end, "file")
            units[unit.address] = unit
            child_addresses.append(unit.address)

    return _with_children(units, root.address, child_addresses)


def _unitize_markdown(artifact: Artifact) -> dict[str, ArtifactUnit]:
    lines = artifact.text.splitlines()
    root = _make_unit(artifact, "document", "document", artifact.path_or_name, 1, max(len(lines), 1), None)
    units = {root.address: root}
    headings: list[tuple[int, str, str]] = []

    for idx, line in enumerate(lines, start=1):
        match = re.match(r"^(#{1,6})\s+(.+)$", line)
        if match:
            title = match.group(2).strip()
            slug = re.sub(r"[^a-z0-9]+", "-", title.lower()).strip("-") or f"section-{idx}"
            headings.append((idx, f"section:{slug}", title))

    child_addresses: list[str] = []
    for pos, (start, address, title) in enumerate(headings):
        end = headings[pos + 1][0] - 1 if pos + 1 < len(headings) else max(len(lines), start)
        unit = _make_unit(artifact, address, "section", title, start, end, "document")
        units[unit.address] = unit
        child_addresses.append(unit.address)

    if not child_addresses:
        paragraph_units = _paragraph_units(artifact, "document")
        units.update(paragraph_units)
        child_addresses.extend(paragraph_units)

    return _with_children(units, root.address, child_addresses)


def _unitize_log(artifact: Artifact) -> dict[str, ArtifactUnit]:
    lines = artifact.text.splitlines()
    root = _make_unit(artifact, "log", "log", artifact.path_or_name, 1, max(len(lines), 1), None)
    units = {root.address: root}
    child_addresses: list[str] = []

    for idx, line in enumerate(lines, start=1):
        lowered = line.lower()
        if any(token in lowered for token in ("error", "failed", "traceback", "exception")):
            start = max(1, idx - 2)
            end = min(max(len(lines), 1), idx + 3)
            address = f"error:{idx}"
            unit = _make_unit(artifact, address, "error", line.strip()[:80] or address, start, end, "log")
            units[unit.address] = unit
            child_addresses.append(unit.address)

    if not child_addresses:
        return _unitize_text(artifact)
    return _with_children(units, root.address, child_addresses)


def _unitize_html(artifact: Artifact) -> dict[str, ArtifactUnit]:
    lines = artifact.text.splitlines()
    root = _make_unit(artifact, "web_page", "web_page", artifact.path_or_name, 1, max(len(lines), 1), None)
    units = {root.address: root}
    child_addresses: list[str] = []
    seen: dict[str, int] = {}
    patterns = [
        (r"<h[1-6][^>]*>(.*?)</h[1-6]>", "heading"),
        (r"<a\b[^>]*>(.*?)</a>", "link"),
        (r"<button\b[^>]*>(.*?)</button>", "ui_element"),
        (r"<input\b[^>]*>", "ui_element"),
        (r"<textarea\b[^>]*>", "ui_element"),
        (r"<select\b[^>]*>", "ui_element"),
    ]
    for idx, line in enumerate(lines, start=1):
        for pattern, kind in patterns:
            for match in re.finditer(pattern, line, flags=re.IGNORECASE):
                raw_title = re.sub(r"<[^>]+>", "", match.group(1) if match.groups() else match.group(0)).strip()
                title = raw_title or kind
                slug = re.sub(r"[^a-z0-9]+", "-", title.lower()).strip("-") or kind
                seen[slug] = seen.get(slug, 0) + 1
                suffix = f"-{seen[slug]}" if seen[slug] > 1 else ""
                address = f"{kind}:{slug}{suffix}"
                unit = _make_unit(artifact, address, kind, title[:80], idx, idx, "web_page")
                units[unit.address] = unit
                child_addresses.append(unit.address)

    if not child_addresses:
        paragraph_units = _paragraph_units(artifact, "web_page")
        units.update(paragraph_units)
        child_addresses.extend(paragraph_units)
    return _with_children(units, root.address, child_addresses)


def _unitize_json(artifact: Artifact) -> dict[str, ArtifactUnit]:
    lines = artifact.text.splitlines()
    try:
        data = json.loads(artifact.text)
    except json.JSONDecodeError:
        return _unitize_text(artifact)

    root_kind = "world_map" if _looks_like_world_map(data) or artifact.kind in {"world_map", "ceiba_world_map"} else "json"
    root = _make_unit(artifact, root_kind, root_kind, artifact.path_or_name, 1, max(len(lines), 1), None)
    units = {root.address: root}
    child_addresses: list[str] = []

    if isinstance(data, dict):
        for surface in _iter_named_records(data, ("surfaces", "surface_records", "surfaceRecords")):
            address = _unique_address(units, f"surface:{_record_slug(surface, ('surface_id', 'surfaceId', 'id', 'handle', 'name', 'title', 'url'))}")
            title = _record_title(surface, ("title", "name", "url", "surface_id", "id"), "surface")
            units[address] = _make_unit(
                artifact,
                address,
                "surface",
                title,
                1,
                max(len(lines), 1),
                root.address,
                inline_text=_inline_json(surface),
            )
            child_addresses.append(address)
            child_addresses.extend(_add_surface_children(artifact, units, surface, address))

        if not child_addresses:
            for key, value in list(data.items())[:30]:
                address = _unique_address(units, f"json:{_slug(str(key))}")
                units[address] = _make_unit(
                    artifact,
                    address,
                    "json_value",
                    str(key)[:80],
                    1,
                    max(len(lines), 1),
                    root.address,
                    inline_text=_inline_json(value),
                )
                child_addresses.append(address)
    elif isinstance(data, list):
        for idx, value in enumerate(data[:30], start=1):
            address = f"json:item-{idx}"
            units[address] = _make_unit(
                artifact,
                address,
                "json_value",
                f"item {idx}",
                1,
                max(len(lines), 1),
                root.address,
                inline_text=_inline_json(value),
            )
            child_addresses.append(address)

    if not child_addresses:
        return _with_children(units, root.address, child_addresses)
    return _with_children(units, root.address, child_addresses)


def _add_surface_children(
    artifact: Artifact,
    units: dict[str, ArtifactUnit],
    surface: object,
    parent_address: str,
) -> list[str]:
    if not isinstance(surface, dict):
        return []
    lines = artifact.text.splitlines()
    child_addresses: list[str] = []
    for element in _iter_named_records(surface, ("elements", "element_records", "elementRecords", "ui_elements", "uiElements")):
        address = _unique_address(
            units,
            f"ui_element:{_record_slug(element, ('element_id', 'elementId', 'id', 'handle', 'text', 'label', 'name', 'role'))}",
        )
        title = _record_title(element, ("text", "label", "name", "role", "element_id", "id"), "ui_element")
        units[address] = _make_unit(
            artifact,
            address,
            "ui_element",
            title,
            1,
            max(len(lines), 1),
            parent_address,
            inline_text=_inline_json(element),
        )
        child_addresses.append(address)

    for block in _iter_named_records(surface, ("semantic_blocks", "semanticBlocks", "blocks", "text_blocks", "textBlocks")):
        address = _unique_address(units, f"semantic_block:{_record_slug(block, ('block_id', 'blockId', 'id', 'text', 'title'))}")
        title = _record_title(block, ("title", "text", "block_id", "id"), "semantic_block")
        units[address] = _make_unit(
            artifact,
            address,
            "semantic_block",
            title,
            1,
            max(len(lines), 1),
            parent_address,
            inline_text=_inline_json(block),
        )
        child_addresses.append(address)

    for region in _iter_named_records(surface, ("image_regions", "imageRegions", "image_tiles", "imageTiles", "tiles")):
        address = _unique_address(units, f"image_region:{_record_slug(region, ('region_id', 'regionId', 'id', 'label', 'title'))}")
        title = _record_title(region, ("label", "title", "region_id", "id"), "image_region")
        units[address] = _make_unit(
            artifact,
            address,
            "image_region",
            title,
            1,
            max(len(lines), 1),
            parent_address,
            inline_text=_inline_json(region),
        )
        child_addresses.append(address)

    parent = units[parent_address]
    units[parent_address] = replace(parent, child_addresses=list(parent.child_addresses) + child_addresses)
    return child_addresses


def _looks_like_world_map(data: object) -> bool:
    return isinstance(data, dict) and any(key in data for key in ("surfaces", "surface_records", "surfaceRecords", "world_map"))


def _iter_named_records(container: dict[str, object], names: tuple[str, ...]) -> list[object]:
    for name in names:
        value = container.get(name)
        if isinstance(value, list):
            return value
        if isinstance(value, dict):
            return list(value.values())
    return []


def _record_slug(record: object, fields: tuple[str, ...]) -> str:
    if isinstance(record, dict):
        for field in fields:
            value = record.get(field)
            if value:
                return _slug(str(value))
    return "record"


def _record_title(record: object, fields: tuple[str, ...], fallback: str) -> str:
    if isinstance(record, dict):
        for field in fields:
            value = record.get(field)
            if value:
                return str(value).strip()[:80]
    return fallback


def _unique_address(units: dict[str, ArtifactUnit], address: str) -> str:
    if address not in units:
        return address
    idx = 2
    while f"{address}-{idx}" in units:
        idx += 1
    return f"{address}-{idx}"


def _slug(text: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-") or "item"


def _inline_json(value: object) -> str:
    return json.dumps(value, indent=2, sort_keys=True, ensure_ascii=True)


def _unitize_text(artifact: Artifact) -> dict[str, ArtifactUnit]:
    lines = artifact.text.splitlines()
    root = _make_unit(artifact, "text", "text", artifact.path_or_name, 1, max(len(lines), 1), None)
    units = {root.address: root}
    child_addresses = list(_paragraph_units(artifact, "text"))
    units.update(_paragraph_units(artifact, "text"))
    return _with_children(units, root.address, child_addresses)


def _paragraph_units(artifact: Artifact, parent: str) -> dict[str, ArtifactUnit]:
    lines = artifact.text.splitlines()
    units: dict[str, ArtifactUnit] = {}
    start: int | None = None
    part = 1
    for idx, line in enumerate(lines + [""], start=1):
        if line.strip() and start is None:
            start = idx
        if start is not None and (not line.strip() or idx > len(lines)):
            end = idx - 1
            address = f"paragraph:{part}"
            title = lines[start - 1].strip()[:80] or address
            units[address] = _make_unit(artifact, address, "paragraph", title, start, end, parent)
            start = None
            part += 1
    return units


def _with_children(units: dict[str, ArtifactUnit], root_address: str, child_addresses: Iterable[str]) -> dict[str, ArtifactUnit]:
    root = units[root_address]
    units[root_address] = replace(root, child_addresses=list(child_addresses))
    return units


def _make_unit(
    artifact: Artifact,
    address: str,
    unit_kind: str,
    title: str,
    start_line: int,
    end_line: int,
    parent_address: str | None,
    inline_text: str | None = None,
) -> ArtifactUnit:
    lines = artifact.text.splitlines()
    text = inline_text if inline_text is not None else ("\n".join(lines[start_line - 1 : end_line]) if lines else artifact.text)
    content_hash = sha256_text(text)
    payload = {
        "artifact_id": artifact.artifact_id,
        "version_hash": artifact.version_hash,
        "address": address,
        "start": start_line,
        "end": end_line,
        "hash": content_hash,
    }
    unit_id = stable_id("unit", payload)
    exact_ref = f"exact:{artifact.artifact_id}:{address}:{content_hash[:12]}"
    return ArtifactUnit(
        unit_id=unit_id,
        artifact_id=artifact.artifact_id,
        address=address,
        unit_kind=unit_kind,
        title=title,
        content_hash=content_hash,
        exact_ref=exact_ref,
        start_line=start_line,
        end_line=end_line,
        parent_address=parent_address,
        inline_text=inline_text,
    )

"""Run fixture packs that contain multiple expected offline probes."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from .records import DeltaStatus
from .runner import run_fixture_data
from .serialization import to_plain


def run_fixture_pack(path: str | Path) -> dict[str, Any]:
    pack_path = Path(path)
    pack = json.loads(pack_path.read_text(encoding="utf-8"))
    case_reports = []
    for case in pack.get("cases", []):
        case_id = case.get("case_id", "case")
        if "fixture" not in case:
            case_reports.append(
                {
                    "case_id": case_id,
                    "passed": False,
                    "reason": "case has no fixture; this pack may be a seed pack, not an executable fixture pack",
                }
            )
            continue
        result = run_fixture_data(case["fixture"])
        expectation = _check_expectations(result, case.get("expect", {}))
        case_reports.append(
            {
                "case_id": case_id,
                "passed": expectation["passed"],
                "reason": expectation["reason"],
                "audit_passed": result.audit_report.passed,
                "report_id": result.audit_report.report_id,
                "readiness": [to_plain(decision) for decision in result.readiness_decisions],
                "information_need": result.context_receipts[0].information_need_classification
                if result.context_receipts
                else {},
                "candidate_dispositions": result.context_receipts[0].candidate_dispositions
                if result.context_receipts
                else [],
                "rejected_delta_refs": [delta.delta_id for delta in result.state_deltas if delta.status == DeltaStatus.REJECTED],
            }
        )
    return {
        "pack_id": pack.get("pack_id", pack_path.stem),
        "path": str(pack_path),
        "case_count": len(case_reports),
        "passed": all(case.get("passed") for case in case_reports),
        "cases": case_reports,
    }


def _check_expectations(result, expect: dict[str, Any]) -> dict[str, Any]:
    if not expect:
        return {"passed": True, "reason": "no explicit expectations"}
    failures: list[str] = []
    if "readiness" in expect:
        expected = expect["readiness"]
        decision = next(
            (item for item in result.readiness_decisions if item.response_type.value == expected.get("response_type")),
            None,
        )
        if decision is None:
            failures.append(f"missing readiness for {expected.get('response_type')}")
        else:
            if decision.status.value != expected.get("status"):
                failures.append(f"readiness status {decision.status.value} != {expected.get('status')}")
            if decision.route.value != expected.get("route"):
                failures.append(f"readiness route {decision.route.value} != {expected.get('route')}")
    if "information_need_classification" in expect:
        actual = (
            result.context_receipts[0].information_need_classification.get("classification")
            if result.context_receipts
            else None
        )
        if actual != expect["information_need_classification"]:
            failures.append(f"information need {actual} != {expect['information_need_classification']}")
    if "candidate_disposition" in expect:
        dispositions = {
            item.get("disposition")
            for receipt in result.context_receipts
            for item in receipt.candidate_dispositions
        }
        if expect["candidate_disposition"] not in dispositions:
            failures.append(f"candidate disposition {expect['candidate_disposition']} missing")
    if "rejected_delta_contains" in expect:
        rejected_reasons = [delta.reason for delta in result.state_deltas if delta.status == DeltaStatus.REJECTED]
        if not any(expect["rejected_delta_contains"] in reason for reason in rejected_reasons):
            failures.append(f"rejected delta reason missing {expect['rejected_delta_contains']}")
    return {"passed": not failures, "reason": "; ".join(failures) if failures else "expectations satisfied"}

"""CurrentFocus selection for the v0.1 workbench."""

from __future__ import annotations

from .hashing import stable_id
from .records import ArtifactReviewStatus, CurrentFocus, EpisodeState, FocusReason, PlanStepStatus


def select_current_focus(state: EpisodeState) -> CurrentFocus:
    layer1 = state.layer1
    active_artifact_id, active_address, exact_refs = _active_target(state)

    if layer1.user_instruction_refs:
        reason = FocusReason.EXPLICIT_USER_INSTRUCTION
        source_refs = [layer1.user_instruction_refs[-1]]
    elif layer1.verifier_failure_refs:
        reason = FocusReason.VERIFIER_FAILURE
        source_refs = [layer1.verifier_failure_refs[-1]]
    elif layer1.blockers:
        reason = FocusReason.UNRESOLVED_BLOCKER
        source_refs = layer1.latest_event_refs[-1:] or []
    else:
        stale = next((artifact for artifact in state.artifacts.values() if artifact.review_status == ArtifactReviewStatus.STALE), None)
        if stale is not None:
            reason = FocusReason.STALE_TARGET
            source_refs = [stale.artifact_id]
            active_artifact_id = stale.artifact_id
            active_address = stale.last_touched_address
            exact_refs = stale.exact_window_refs
        else:
            active_step = _active_plan_step(state)
            if active_step is not None:
                reason = FocusReason.CURRENT_PLAN_STEP
                source_refs = [active_step.step_id] + active_step.source_refs
                active_artifact_id = active_step.target_artifact_ref or active_artifact_id
                active_address = active_step.target_address or active_address
            elif active_artifact_id:
                reason = FocusReason.LAST_CHANGED_ARTIFACT
                source_refs = [active_artifact_id]
            else:
                reason = FocusReason.MODEL_ASSISTED_PLANNING_NEEDED
                source_refs = layer1.latest_event_refs[-1:] or []

    focus_payload = {
        "episode_id": state.episode_id,
        "reason": reason.value,
        "source_refs": source_refs,
        "active_artifact": active_artifact_id,
        "active_address": active_address,
    }
    return CurrentFocus(
        focus_id=stable_id("focus", focus_payload),
        reason_code=reason,
        source_refs=source_refs,
        active_artifact_ref=active_artifact_id,
        active_address=active_address,
        exact_window_refs=exact_refs[:4],
        latest_result_refs=layer1.verifier_failure_refs[-1:] or layer1.latest_event_refs[-1:],
        permitted_action_class="proposal_only",
    )


def _active_plan_step(state: EpisodeState):
    if state.plan is None:
        return None
    for step in state.plan.steps:
        if step.status == PlanStepStatus.ACTIVE:
            return step
    for step in state.plan.steps:
        if step.status == PlanStepStatus.PENDING:
            return step
    return None


def _active_target(state: EpisodeState) -> tuple[str | None, str | None, list[str]]:
    active_step = _active_plan_step(state)
    if active_step is not None and active_step.target_artifact_ref:
        artifact = state.artifacts.get(active_step.target_artifact_ref)
        if artifact is not None:
            return artifact.artifact_id, active_step.target_address, artifact.exact_window_refs

    if not state.artifacts:
        return None, None, []
    changed = next((item for item in state.artifacts.values() if item.review_status == ArtifactReviewStatus.CHANGED), None)
    artifact = changed or next(iter(state.artifacts.values()))
    return artifact.artifact_id, artifact.last_touched_address, artifact.exact_window_refs

"""Stable hashing helpers for records, blobs, and rendered context."""

from __future__ import annotations

import hashlib
import json
from dataclasses import asdict, is_dataclass
from enum import Enum
from typing import Any


def canonical_json(value: Any) -> str:
    """Return stable JSON for hashable record content."""

    def normalize(item: Any) -> Any:
        if isinstance(item, Enum):
            return item.value
        if is_dataclass(item):
            return normalize(asdict(item))
        if isinstance(item, dict):
            return {str(k): normalize(v) for k, v in sorted(item.items(), key=lambda kv: str(kv[0]))}
        if isinstance(item, (list, tuple, set)):
            return [normalize(v) for v in item]
        return item

    return json.dumps(normalize(value), sort_keys=True, separators=(",", ":"), ensure_ascii=True)


def sha256_text(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def stable_id(prefix: str, value: Any, length: int = 16) -> str:
    return f"{prefix}_{sha256_text(canonical_json(value))[:length]}"

"""Offline policy classifications for context and acceptance audits."""

from __future__ import annotations

from .artifact_units import resolve_address
from .records import (
    AcceptanceCriterionClass,
    AddressMap,
    ArtifactReviewStatus,
    CriterionArtifact,
    CurrentFocus,
    EpisodeState,
    InformationNeedClass,
    SummaryNode,
)

MECHANICAL_CHECK_TYPES = {
    "python_syntax",
    "contains",
    "not_contains",
    "regex",
    "verifier_log_passed",
    "required_headings",
    "section_contains",
    "no_unresolved_markers",
    "word_count_min",
    "command",
    "shell_command",
}

SEMANTIC_CHECK_TYPES = {"semantic_review", "model_review", "llm_review"}
OPERATOR_CHECK_TYPES = {"human", "human_review", "operator", "operator_review", "manual_review"}
UNVERIFIABLE_CHECK_TYPES = {"unverifiable", "unknown"}


def classify_focus_information_need(
    state: EpisodeState,
    focus: CurrentFocus,
    *,
    address_maps: dict[str, AddressMap],
) -> dict[str, str]:
    """Classify the context need for the next model call.

    This is deterministic scaffolding, not a prediction of model quality. It
    tells the host whether the current focus is exact-ready, summary/card-ready,
    handle-only, under-specified, or needs decomposition before useful work.
    """

    if not state.artifacts:
        return _need(InformationNeedClass.NEEDS_DECOMPOSITION, "no artifacts are mapped for the episode")
    if focus.active_artifact_ref is None:
        return _need(InformationNeedClass.HANDLE_SUFFICIENT, "artifacts exist but no active artifact is selected")
    artifact_state = state.artifacts.get(focus.active_artifact_ref)
    if artifact_state is None:
        return _need(InformationNeedClass.INSUFFICIENT_CONTEXT, "active artifact is missing from EpisodeState")
    if artifact_state.review_status == ArtifactReviewStatus.STALE:
        return _need(InformationNeedClass.EXACT_REQUIRED, "active artifact is stale and must be refreshed or reopened")
    if focus.active_address and resolve_address(address_maps, focus.active_address) is None:
        return _need(InformationNeedClass.INSUFFICIENT_CONTEXT, "active address does not resolve in the current artifact map")
    if focus.exact_window_refs:
        return _need(InformationNeedClass.EXACT_REQUIRED, "current focus has visible exact material")
    if artifact_state.address_map_ref:
        return _need(InformationNeedClass.CARD_SUFFICIENT, "active artifact has a map and summary but no exact window")
    return _need(InformationNeedClass.INSUFFICIENT_CONTEXT, "active artifact lacks a usable map or exact window")


def classify_criterion(criterion: CriterionArtifact) -> dict[str, str]:
    check_type = criterion.check_type
    if check_type in MECHANICAL_CHECK_TYPES:
        criterion_class = AcceptanceCriterionClass.MECHANICAL
        reason = "deterministic host-verifiable criterion"
    elif check_type in SEMANTIC_CHECK_TYPES:
        criterion_class = AcceptanceCriterionClass.SEMANTIC_ADVISORY
        reason = "requires semantic judgment; model output is advisory until confirmed"
    elif check_type in OPERATOR_CHECK_TYPES:
        criterion_class = AcceptanceCriterionClass.OPERATOR_REQUIRED
        reason = "requires operator or human confirmation"
    elif check_type in UNVERIFIABLE_CHECK_TYPES:
        criterion_class = AcceptanceCriterionClass.UNVERIFIABLE
        reason = "no deterministic verifier is available"
    else:
        criterion_class = AcceptanceCriterionClass.UNVERIFIABLE
        reason = f"unsupported check_type {check_type}"
    return {
        "criterion_id": criterion.criterion_id,
        "check_type": check_type,
        "classification": criterion_class.value,
        "reason": reason,
    }


def classify_criteria(criteria: list[CriterionArtifact]) -> list[dict[str, str]]:
    return [classify_criterion(criterion) for criterion in criteria]


def audit_summary_claims(summaries: dict[str, SummaryNode]) -> list[dict[str, object]]:
    """Check that non-empty summary claim axes have exact descent handles.

    The summaries remain non-authoritative. This audit catches the failure mode
    where a compact parent view starts making claims without any path back to
    exact child evidence.
    """

    audits: list[dict[str, object]] = []
    for summary in summaries.values():
        claim_axes = _non_empty_claim_axes(summary)
        evidence_refs = list(summary.exact_descents)
        missing_evidence = bool(claim_axes) and not evidence_refs
        bad_refs = [ref for ref in evidence_refs if not ref.startswith("exact:")]
        status = "failed" if missing_evidence or bad_refs else "passed"
        reason = "summary claim axes have exact descent refs"
        if missing_evidence:
            reason = "summary has claim-like axes without exact descent refs"
        elif bad_refs:
            reason = "summary exact descents contain invalid refs"
        audits.append(
            {
                "summary_id": summary.summary_id,
                "policy_id": summary.policy_id,
                "status": status,
                "claim_axes": claim_axes,
                "evidence_refs": evidence_refs[:12],
                "reason": reason,
            }
        )
    return audits


def _need(need_class: InformationNeedClass, reason: str) -> dict[str, str]:
    return {"classification": need_class.value, "reason": reason}


def _non_empty_claim_axes(summary: SummaryNode) -> list[str]:
    axes = summary.axes
    claim_axes: list[str] = []
    for key in ("claims_facts", "interfaces_dependencies", "constraints", "current_state", "risks_unknowns"):
        value = axes.get(key)
        if value:
            claim_axes.append(key)
    return claim_axes

"""Readiness matrix for model proposals."""

from __future__ import annotations

from .artifact_units import resolve_address
from .hashing import stable_id
from .records import (
    AddressMap,
    ArtifactReviewStatus,
    CurrentFocus,
    EpisodeState,
    ModelResponse,
    ReadinessDecision,
    ReadinessStatus,
    RejectionRoute,
    ResponseType,
)


VAGUE_REQUESTS = {
    "",
    "more",
    "more context",
    "context",
    "all",
    "everything",
    "the file",
    "source",
    "more info",
}


def check_readiness(
    state: EpisodeState,
    focus: CurrentFocus,
    response: ModelResponse,
    *,
    address_maps: dict[str, AddressMap],
    patch_preview_ids: set[str] | None = None,
) -> ReadinessDecision:
    if response.response_type == ResponseType.REQUEST_EXACT:
        return _check_request_exact(response, address_maps)
    if response.response_type == ResponseType.DRAFT_CHANGE:
        return _check_draft_change(state, focus, response)
    if response.response_type == ResponseType.APPLY_CHANGE:
        return _check_apply_change(response, patch_preview_ids or set())
    if response.response_type == ResponseType.FINAL_ANSWER:
        return _check_final_answer(focus, response)
    if response.response_type == ResponseType.ASK_USER:
        return _ready(response, "user clarification requested")
    if response.response_type in {ResponseType.PLAN_NEXT, ResponseType.REVIEW_RESULT}:
        return _ready(response, "proposal/review response is host-reviewable")
    return _blocked(response, "unsupported response type", RejectionRoute.ASK_USER)


def _check_request_exact(response: ModelResponse, address_maps: dict[str, AddressMap]) -> ReadinessDecision:
    requested = (response.requested_ref_or_address or "").strip()
    if requested.lower() in VAGUE_REQUESTS:
        return _blocked(
            response,
            "REQUEST_EXACT is vague; host must return an address map or ask a narrow question, not run broad retrieval",
            RejectionRoute.REFRESH_OR_REOPEN_CONTEXT,
        )
    if resolve_address(address_maps, requested) is None:
        return _blocked(
            response,
            f"REQUEST_EXACT handle is not visible or resolvable: {requested}",
            RejectionRoute.REFRESH_OR_REOPEN_CONTEXT,
            required_refs=[requested],
        )
    return _ready(response, "exact handle is visible and bounded", required_refs=[requested])


def _check_draft_change(state: EpisodeState, focus: CurrentFocus, response: ModelResponse) -> ReadinessDecision:
    if not focus.active_artifact_ref:
        return _blocked(response, "DRAFT_CHANGE has no active artifact", RejectionRoute.ASK_USER)
    artifact = state.artifacts.get(focus.active_artifact_ref)
    if artifact is None:
        return _blocked(response, "DRAFT_CHANGE active artifact is missing from state", RejectionRoute.REPAIR_MAP_OR_SUMMARY)
    if artifact.review_status == ArtifactReviewStatus.STALE:
        return _blocked(response, "DRAFT_CHANGE target artifact map/hash is stale", RejectionRoute.REFRESH_OR_REOPEN_CONTEXT)
    if not focus.exact_window_refs:
        return _blocked(response, "DRAFT_CHANGE requires an exact active window", RejectionRoute.REFRESH_OR_REOPEN_CONTEXT)
    if not response.draft:
        return _blocked(response, "DRAFT_CHANGE is missing draft text", RejectionRoute.FIX_ACTION)
    return _ready(response, "exact active window and current artifact state are visible", required_refs=focus.exact_window_refs)


def _check_final_answer(focus: CurrentFocus, response: ModelResponse) -> ReadinessDecision:
    if response.reasoning_only:
        return _ready(response, "FINAL_ANSWER explicitly marked reasoning-only")
    visible = set(focus.exact_window_refs)
    if not response.support_refs or not visible.intersection(response.support_refs):
        return _blocked(
            response,
            "FINAL_ANSWER has source-grounded claims without visible exact support",
            RejectionRoute.REFRESH_OR_REOPEN_CONTEXT,
            required_refs=response.support_refs,
        )
    return _ready(response, "FINAL_ANSWER has visible exact support", required_refs=response.support_refs)


def _check_apply_change(response: ModelResponse, patch_preview_ids: set[str]) -> ReadinessDecision:
    if not response.preview_id:
        return _blocked(response, "APPLY_CHANGE requires a preview_id", RejectionRoute.FIX_ACTION)
    if response.preview_id not in patch_preview_ids:
        return _blocked(response, f"APPLY_CHANGE preview_id is unknown or stale: {response.preview_id}", RejectionRoute.FIX_ACTION)
    if not (response.operator_confirmed or response.verifier_confirmed):
        return _blocked(
            response,
            "APPLY_CHANGE requires operator_confirmed or verifier_confirmed",
            RejectionRoute.ASK_USER,
            required_refs=[response.preview_id],
        )
    return _ready(response, "APPLY_CHANGE has known preview and confirmation", required_refs=[response.preview_id])


def _ready(response: ModelResponse, reason: str, required_refs: list[str] | None = None) -> ReadinessDecision:
    return ReadinessDecision(
        decision_id=stable_id("ready", {"type": response.response_type.value, "reason": reason, "refs": required_refs or []}),
        status=ReadinessStatus.READY,
        response_type=response.response_type,
        reason=reason,
        required_refs=required_refs or [],
    )


def _blocked(
    response: ModelResponse,
    reason: str,
    route: RejectionRoute,
    required_refs: list[str] | None = None,
) -> ReadinessDecision:
    return ReadinessDecision(
        decision_id=stable_id("blocked", {"type": response.response_type.value, "reason": reason, "refs": required_refs or []}),
        status=ReadinessStatus.BLOCKED,
        response_type=response.response_type,
        reason=reason,
        route=route,
        required_refs=required_refs or [],
    )

"""Rejection routing for blocked readiness and rejected deltas."""

from __future__ import annotations

from .hashing import stable_id
from .records import (
    DeltaStatus,
    ReadinessDecision,
    ReadinessStatus,
    RejectionRoute,
    RejectionRouteRecord,
    ResponseType,
    StateDelta,
)


def routes_for_transition(decision: ReadinessDecision, deltas: list[StateDelta]) -> list[RejectionRouteRecord]:
    routes: list[RejectionRouteRecord] = []
    if decision.status == ReadinessStatus.BLOCKED:
        routes.append(
            RejectionRouteRecord(
                route_id=stable_id("route", {"decision": decision.decision_id, "route": decision.route.value}),
                route=decision.route,
                reason=decision.reason,
                source_refs=[decision.decision_id],
                next_response_type=_next_response_for_route(decision.route),
            )
        )

    for delta in deltas:
        if delta.status == DeltaStatus.REJECTED:
            route = RejectionRoute.ASK_USER if "done" in delta.reason else RejectionRoute.FIX_ACTION
            routes.append(
                RejectionRouteRecord(
                    route_id=stable_id("route", {"delta": delta.delta_id, "route": route.value}),
                    route=route,
                    reason=delta.reason,
                    source_refs=[delta.delta_id],
                    next_response_type=_next_response_for_route(route),
                )
            )
    return routes


def _next_response_for_route(route: RejectionRoute) -> ResponseType | None:
    if route in {RejectionRoute.REFRESH_OR_REOPEN_CONTEXT, RejectionRoute.REPAIR_MAP_OR_SUMMARY}:
        return ResponseType.REQUEST_EXACT
    if route == RejectionRoute.REDECOMPOSE_TASK:
        return ResponseType.PLAN_NEXT
    if route == RejectionRoute.ASK_USER:
        return ResponseType.ASK_USER
    if route == RejectionRoute.FIX_ACTION:
        return ResponseType.DRAFT_CHANGE
    return None

"""Saved-run importers for offline audit fixtures."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from .importers import fixture_from_directory

JSONL_EVENT_NAME_HINTS = (
    "artifact",
    "assembly",
    "controller",
    "event",
    "evidence",
    "layer0",
    "message",
    "plan",
    "provider",
    "receipt",
    "result",
    "run",
    "task_state",
    "tool",
    "trace",
    "usage",
    "view",
)

EMBEDDED_ARTIFACT_RECORD_TYPES = {"artifacts", "evidence"}
MAX_JSONL_BYTES = 2_000_000
MAX_JSONL_LINES = 1000
MAX_EMBEDDED_ARTIFACTS = 80
MAX_EMBEDDED_TEXT_CHARS = 80_000


def fixture_from_saved_run(
    directory: str | Path,
    *,
    kind: str = "auto",
    objective: str | None = None,
) -> dict[str, Any]:
    root = Path(directory).resolve()
    detected = _detect_kind(root) if kind == "auto" else kind
    fixture = fixture_from_directory(root, objective=objective or f"Offline audit for {detected} saved run {root}")
    fixture["saved_run_kind"] = detected
    fixture["events"].extend(_events_from_jsonl(root, detected))
    fixture["artifacts"].extend(_embedded_artifacts_from_jsonl(root))
    return fixture


def _detect_kind(root: Path) -> str:
    names = {path.name.lower() for path in root.rglob("*") if path.is_file()}
    joined = " ".join(sorted(names))
    if "provider" in joined or "prompt" in joined or "working_brief" in joined:
        return "minimalist"
    if "layer0" in joined or "reconstitution" in joined or "spar_harness" in joined:
        return "spar_harness"
    return "generic"


def _events_from_jsonl(root: Path, detected: str) -> list[dict[str, Any]]:
    events: list[dict[str, Any]] = []
    for path in sorted(root.rglob("*.jsonl")):
        if path.stat().st_size > MAX_JSONL_BYTES:
            continue
        if not _looks_like_saved_run_jsonl(path):
            continue
        for idx, item in enumerate(_read_jsonl_lines(path), start=1):
            if idx > MAX_JSONL_LINES:
                break
            event = _event_from_item(item, path, detected)
            if event is not None:
                events.append(event)
    return events


def _event_from_item(item: dict[str, Any], path: Path, detected: str) -> dict[str, Any] | None:
    payload = item.get("payload") if isinstance(item.get("payload"), dict) else item
    record_type = str(item.get("record_type") or "").lower()
    event_type = str(item.get("event_type") or "").lower()
    kind = str(item.get("kind") or item.get("event_kind") or item.get("type") or record_type or event_type or "").lower()
    role = str(item.get("role") or payload.get("role") or "").lower()
    actor = str(item.get("actor") or item.get("actor_kind") or item.get("actor_id") or role or "host")

    if role == "user" or "user" in kind or actor == "user":
        event_kind = "user_instruction"
    elif role == "system":
        event_kind = "system_instruction"
    elif role == "assistant":
        event_kind = "model_response"
    elif role == "tool":
        event_kind = "tool_result"
    elif item.get("event_kind"):
        event_kind = str(item["event_kind"])
    elif event_type in {"request", "response"}:
        event_kind = f"provider_{event_type}"
    elif record_type:
        event_kind = _event_kind_from_record_type(record_type, payload, path)
    elif "verifier" in kind or "test" in kind:
        event_kind = "verifier_result"
    elif "tool" in kind:
        event_kind = "tool_result"
    elif kind:
        event_kind = kind
    else:
        event_kind = _event_kind_from_path(path)
    if event_kind is None:
        return None

    normalized_payload = dict(payload)
    if "content" in item and "content" not in normalized_payload:
        normalized_payload["content"] = item["content"]
    if role and "role" not in normalized_payload:
        normalized_payload["role"] = role
    if "record_id" in item and "record_id" not in normalized_payload:
        normalized_payload["record_id"] = item["record_id"]
    if record_type and "record_type" not in normalized_payload:
        normalized_payload["record_type"] = record_type
    if event_type and "event_type" not in normalized_payload:
        normalized_payload["event_type"] = event_type
    return {
        "kind": event_kind,
        "actor": actor,
        "payload": {
            "saved_run_kind": detected,
            "source_file": str(path),
            **normalized_payload,
        },
    }


def _event_kind_from_record_type(record_type: str, payload: dict[str, Any], path: Path) -> str:
    if record_type == "artifacts":
        artifact_kind = str(payload.get("artifact_kind") or "").lower()
        if artifact_kind in {"provider_request", "provider_response"}:
            return f"{artifact_kind}_artifact"
        return "artifact_record"
    if record_type == "provider_io":
        return "provider_io_record"
    if record_type == "evidence":
        nested = payload.get("payload") if isinstance(payload.get("payload"), dict) else {}
        if nested.get("tool_name"):
            return "tool_result"
        return "evidence_record"
    if record_type == "task_states":
        return "task_state"
    if record_type == "views":
        return "view_record"
    if record_type == "receipts":
        return "receipt_record"
    if record_type == "plan_candidates":
        return "plan_candidate"
    return _event_kind_from_path(path) or record_type


def _event_kind_from_path(path: Path) -> str | None:
    lower = path.name.lower()
    if "assembly_receipt" in lower:
        return "reconstitution_receipt"
    if "usage_record" in lower:
        return "usage_record"
    if "tool_result" in lower:
        return "tool_result"
    if "tool_call" in lower:
        return "tool_call"
    if "tool_execution" in lower:
        return "tool_execution"
    if "controller" in lower:
        return "controller_event"
    if "message" in lower:
        return "message"
    if "provider" in lower:
        return "provider_io_record"
    if "receipt" in lower:
        return "receipt_record"
    if "evidence" in lower:
        return "evidence_record"
    if "view" in lower:
        return "view_record"
    if "task_state" in lower:
        return "task_state"
    if "plan" in lower:
        return "plan_candidate"
    if "run" in lower:
        return "run_record"
    if "event" in lower or "layer0" in lower:
        return "event"
    return None


def _embedded_artifacts_from_jsonl(root: Path) -> list[dict[str, Any]]:
    artifacts: list[dict[str, Any]] = []
    for path in sorted(root.rglob("*.jsonl")):
        if len(artifacts) >= MAX_EMBEDDED_ARTIFACTS:
            break
        if path.stat().st_size > MAX_JSONL_BYTES:
            continue
        if not _looks_like_saved_run_jsonl(path):
            continue
        for idx, item in enumerate(_read_jsonl_lines(path), start=1):
            if idx > MAX_JSONL_LINES or len(artifacts) >= MAX_EMBEDDED_ARTIFACTS:
                break
            embedded = _embedded_artifact_from_item(item, path, idx)
            if embedded is not None:
                artifacts.append(embedded)
    return artifacts


def _embedded_artifact_from_item(item: dict[str, Any], path: Path, line_number: int) -> dict[str, Any] | None:
    record_type = str(item.get("record_type") or "").lower()
    if record_type not in EMBEDDED_ARTIFACT_RECORD_TYPES:
        return None
    payload = item.get("payload") if isinstance(item.get("payload"), dict) else {}
    if record_type == "artifacts":
        if payload.get("content_available") is False or "content" not in payload:
            return None
        name = str(payload.get("artifact_ref") or item.get("record_id") or f"{path.stem}_{line_number}")
        kind = str(payload.get("artifact_kind") or "artifact")
        text = _stringify_embedded_content(payload.get("content"))
        suffix = ".json" if text.lstrip().startswith(("{", "[")) else ".txt"
        return {
            "kind": "json" if suffix == ".json" else "text",
            "path_or_name": f"embedded/{name}_{kind}{suffix}",
            "text": _truncate_embedded_text(text),
        }
    nested = payload.get("payload") if isinstance(payload.get("payload"), dict) else {}
    content = nested.get("content")
    if not isinstance(content, str) or not content:
        return None
    name = str(payload.get("evidence_id") or item.get("record_id") or f"{path.stem}_{line_number}")
    return {
        "kind": "text",
        "path_or_name": f"embedded/{name}_evidence.txt",
        "text": _truncate_embedded_text(content),
    }


def _stringify_embedded_content(content: Any) -> str:
    if isinstance(content, str):
        return content
    return json.dumps(content, indent=2, sort_keys=True)


def _truncate_embedded_text(text: str) -> str:
    if len(text) <= MAX_EMBEDDED_TEXT_CHARS:
        return text
    return text[:MAX_EMBEDDED_TEXT_CHARS] + "\n[truncated saved-run embedded artifact]"


def _looks_like_saved_run_jsonl(path: Path) -> bool:
    lower = path.name.lower()
    return any(token in lower for token in JSONL_EVENT_NAME_HINTS)


def _read_jsonl_lines(path: Path) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
        try:
            item = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(item, dict):
            items.append(item)
    return items

"""Serialization helpers for CLI output and fixture assertions."""

from __future__ import annotations

from dataclasses import asdict, is_dataclass
from enum import Enum
from typing import Any


def to_plain(value: Any) -> Any:
    if isinstance(value, Enum):
        return value.value
    if is_dataclass(value):
        return to_plain(asdict(value))
    if isinstance(value, dict):
        return {str(k): to_plain(v) for k, v in value.items()}
    if isinstance(value, list):
        return [to_plain(v) for v in value]
    if isinstance(value, tuple):
        return [to_plain(v) for v in value]
    return value

"""Create deterministic verifier events from recorded log artifacts."""

from __future__ import annotations

from .content_log import ContentLog
from .records import Artifact, Layer0Event


FAIL_TOKENS = ("failed", "failure", "error", "traceback", "exception", "assertionerror")
PASS_TOKENS = ("passed", "success", "ok")


def append_verifier_events_from_artifacts(log: ContentLog, artifacts: dict[str, Artifact]) -> list[Layer0Event]:
    events: list[Layer0Event] = []
    for artifact in artifacts.values():
        if artifact.kind not in {"log", "verifier", "transcript"} and not artifact.path_or_name.lower().endswith((".log", ".out", ".err")):
            continue
        lowered = artifact.text.lower()
        if any(token in lowered for token in FAIL_TOKENS):
            status = "failed"
            message = _first_matching_line(artifact.text, FAIL_TOKENS) or "verifier log contains failure token"
        elif any(token in lowered for token in PASS_TOKENS):
            status = "passed"
            message = _first_matching_line(artifact.text, PASS_TOKENS) or "verifier log contains pass token"
        else:
            continue
        events.append(
            log.append_event(
                kind="verifier_result",
                actor="host",
                payload={
                    "status": status,
                    "message": message,
                    "artifact_id": artifact.artifact_id,
                    "path_or_name": artifact.path_or_name,
                },
                refs=[artifact.blob_ref],
            )
        )
    return events


def _first_matching_line(text: str, tokens: tuple[str, ...]) -> str | None:
    for line in text.splitlines():
        lowered = line.lower()
        if any(token in lowered for token in tokens):
            return line.strip()
    return None

"""Deterministic offline criterion checks."""

from __future__ import annotations

import ast
import re
import subprocess
import tempfile
from pathlib import Path, PurePosixPath

from .hashing import stable_id
from .records import Artifact, CriterionArtifact, VerifierReceipt, VerifierStatus

DEFAULT_COMMAND_PREFIXES = (
    ("python", "-m", "pytest"),
    ("python", "-m", "py_compile"),
    ("python", "-m", "compileall"),
    ("python3", "-m", "pytest"),
    ("python3", "-m", "py_compile"),
    ("python3", "-m", "compileall"),
    ("py", "-m", "pytest"),
    ("py", "-m", "py_compile"),
    ("pytest",),
)
MAX_COMMAND_TIMEOUT_SECONDS = 60
MAX_COMMAND_OUTPUT_CHARS = 1600


def run_criterion_checks(criteria: list[CriterionArtifact], artifacts: dict[str, Artifact]) -> list[VerifierReceipt]:
    receipts: list[VerifierReceipt] = []
    for criterion in criteria:
        if criterion.check_type in {"command", "shell_command"}:
            receipts.append(_check_command(criterion, artifacts))
            continue
        artifact = _target_artifact(criterion, artifacts)
        if artifact is None:
            receipts.append(_receipt(criterion, VerifierStatus.SKIPPED, "no target artifact resolved", None))
            continue
        if criterion.check_type == "python_syntax":
            receipts.append(_check_python_syntax(criterion, artifact))
        elif criterion.check_type == "contains":
            receipts.append(_check_contains(criterion, artifact))
        elif criterion.check_type == "not_contains":
            receipts.append(_check_not_contains(criterion, artifact))
        elif criterion.check_type == "regex":
            receipts.append(_check_regex(criterion, artifact))
        elif criterion.check_type == "verifier_log_passed":
            receipts.append(_check_verifier_log_passed(criterion, artifact))
        elif criterion.check_type == "required_headings":
            receipts.append(_check_required_headings(criterion, artifact))
        elif criterion.check_type == "section_contains":
            receipts.append(_check_section_contains(criterion, artifact))
        elif criterion.check_type == "no_unresolved_markers":
            receipts.append(_check_no_unresolved_markers(criterion, artifact))
        elif criterion.check_type == "word_count_min":
            receipts.append(_check_word_count_min(criterion, artifact))
        else:
            receipts.append(_receipt(criterion, VerifierStatus.SKIPPED, f"unsupported check_type {criterion.check_type}", artifact))
    return receipts


def _target_artifact(criterion: CriterionArtifact, artifacts: dict[str, Artifact]) -> Artifact | None:
    if criterion.target_artifact_ref and criterion.target_artifact_ref in artifacts:
        return artifacts[criterion.target_artifact_ref]
    if criterion.target_path:
        for artifact in artifacts.values():
            if artifact.path_or_name == criterion.target_path:
                return artifact
    if len(artifacts) == 1:
        return next(iter(artifacts.values()))
    return None


def _check_python_syntax(criterion: CriterionArtifact, artifact: Artifact) -> VerifierReceipt:
    try:
        ast.parse(artifact.text)
    except SyntaxError as exc:
        return _receipt(criterion, VerifierStatus.FAILED, f"python syntax failed: {exc}", artifact)
    return _receipt(criterion, VerifierStatus.PASSED, "python syntax passed", artifact)


def _check_contains(criterion: CriterionArtifact, artifact: Artifact) -> VerifierReceipt:
    needle = str(criterion.params.get("text", ""))
    if not needle:
        return _receipt(criterion, VerifierStatus.SKIPPED, "contains check missing params.text", artifact)
    if needle in artifact.text:
        return _receipt(criterion, VerifierStatus.PASSED, "required text found", artifact)
    return _receipt(criterion, VerifierStatus.FAILED, "required text not found", artifact)


def _check_not_contains(criterion: CriterionArtifact, artifact: Artifact) -> VerifierReceipt:
    needle = str(criterion.params.get("text", ""))
    if not needle:
        return _receipt(criterion, VerifierStatus.SKIPPED, "not_contains check missing params.text", artifact)
    if needle not in artifact.text:
        return _receipt(criterion, VerifierStatus.PASSED, "forbidden text absent", artifact)
    return _receipt(criterion, VerifierStatus.FAILED, "forbidden text present", artifact)


def _check_regex(criterion: CriterionArtifact, artifact: Artifact) -> VerifierReceipt:
    pattern = str(criterion.params.get("pattern", ""))
    if not pattern:
        return _receipt(criterion, VerifierStatus.SKIPPED, "regex check missing params.pattern", artifact)
    if re.search(pattern, artifact.text, flags=re.MULTILINE):
        return _receipt(criterion, VerifierStatus.PASSED, "regex matched", artifact)
    return _receipt(criterion, VerifierStatus.FAILED, "regex did not match", artifact)


def _check_verifier_log_passed(criterion: CriterionArtifact, artifact: Artifact) -> VerifierReceipt:
    lowered = artifact.text.lower()
    if any(token in lowered for token in ("failed", "failure", "error", "traceback", "exception", "assertionerror")):
        return _receipt(criterion, VerifierStatus.FAILED, "verifier log contains failure signal", artifact)
    if any(token in lowered for token in ("passed", "success", "ok")):
        return _receipt(criterion, VerifierStatus.PASSED, "verifier log contains pass signal", artifact)
    return _receipt(criterion, VerifierStatus.SKIPPED, "verifier log contains no pass/fail signal", artifact)


def _check_required_headings(criterion: CriterionArtifact, artifact: Artifact) -> VerifierReceipt:
    required = criterion.params.get("headings")
    if not isinstance(required, list) or not required:
        return _receipt(criterion, VerifierStatus.SKIPPED, "required_headings check missing params.headings", artifact)
    present = {_normalize_heading(title) for title, _start, _end in _markdown_sections(artifact.text)}
    missing = [str(title) for title in required if _normalize_heading(str(title)) not in present]
    if not missing:
        return _receipt(criterion, VerifierStatus.PASSED, "required headings present", artifact)
    return _receipt(criterion, VerifierStatus.FAILED, f"missing headings: {', '.join(missing)}", artifact)


def _check_section_contains(criterion: CriterionArtifact, artifact: Artifact) -> VerifierReceipt:
    needle = str(criterion.params.get("text", ""))
    heading = criterion.params.get("heading") or criterion.params.get("section")
    address = criterion.params.get("address")
    if not needle:
        return _receipt(criterion, VerifierStatus.SKIPPED, "section_contains check missing params.text", artifact)
    if not heading and isinstance(address, str) and address.startswith("section:"):
        heading = address.removeprefix("section:").replace("-", " ")
    if not heading:
        return _receipt(criterion, VerifierStatus.SKIPPED, "section_contains check missing params.heading or params.address", artifact)
    section = _section_text(artifact.text, str(heading))
    if section is None:
        return _receipt(criterion, VerifierStatus.FAILED, f"section not found: {heading}", artifact)
    if needle in section:
        return _receipt(criterion, VerifierStatus.PASSED, "section contains required text", artifact)
    return _receipt(criterion, VerifierStatus.FAILED, "section missing required text", artifact)


def _check_no_unresolved_markers(criterion: CriterionArtifact, artifact: Artifact) -> VerifierReceipt:
    markers = criterion.params.get("markers")
    marker_values = [str(item) for item in markers] if isinstance(markers, list) and markers else ["TODO", "TBD", "FIXME", "???"]
    lowered = artifact.text.lower()
    found = [marker for marker in marker_values if marker.lower() in lowered]
    if not found:
        return _receipt(criterion, VerifierStatus.PASSED, "no unresolved markers found", artifact)
    return _receipt(criterion, VerifierStatus.FAILED, f"unresolved markers found: {', '.join(found)}", artifact)


def _check_word_count_min(criterion: CriterionArtifact, artifact: Artifact) -> VerifierReceipt:
    try:
        minimum = int(criterion.params.get("min_words"))
    except (TypeError, ValueError):
        return _receipt(criterion, VerifierStatus.SKIPPED, "word_count_min check missing integer params.min_words", artifact)
    count = len(re.findall(r"\b\w+\b", artifact.text))
    if count >= minimum:
        return _receipt(criterion, VerifierStatus.PASSED, f"word count {count} >= {minimum}", artifact)
    return _receipt(criterion, VerifierStatus.FAILED, f"word count {count} < {minimum}", artifact)


def _markdown_sections(text: str) -> list[tuple[str, int, int]]:
    lines = text.splitlines()
    headings: list[tuple[str, int]] = []
    for idx, line in enumerate(lines, start=1):
        match = re.match(r"^(#{1,6})\s+(.+)$", line)
        if match:
            headings.append((match.group(2).strip(), idx))
    sections: list[tuple[str, int, int]] = []
    for pos, (title, start) in enumerate(headings):
        end = headings[pos + 1][1] - 1 if pos + 1 < len(headings) else max(len(lines), start)
        sections.append((title, start, end))
    return sections


def _section_text(text: str, heading: str) -> str | None:
    lines = text.splitlines()
    wanted = _normalize_heading(heading)
    for title, start, end in _markdown_sections(text):
        if _normalize_heading(title) == wanted:
            return "\n".join(lines[start - 1 : end])
    return None


def _normalize_heading(text: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")


def _check_command(criterion: CriterionArtifact, artifacts: dict[str, Artifact]) -> VerifierReceipt:
    command = criterion.params.get("command")
    if not isinstance(command, list) or not command or not all(isinstance(part, str) for part in command):
        return _receipt(criterion, VerifierStatus.SKIPPED, "command check requires params.command as a string list", None)
    if not _command_is_allowed(command, criterion):
        return _receipt(criterion, VerifierStatus.SKIPPED, "command prefix is not in the offline verifier allowlist", None)

    timeout = _bounded_timeout(criterion.params.get("timeout_seconds"))
    expected_exit = int(criterion.params.get("expected_exit_code", 0))
    with tempfile.TemporaryDirectory(prefix="ail_verify_") as temp_name:
        workspace = Path(temp_name)
        _materialize_artifacts(workspace, artifacts)
        cwd = _resolve_safe_cwd(workspace, str(criterion.params.get("cwd", ".")))
        if cwd is None:
            return _receipt(criterion, VerifierStatus.SKIPPED, "command cwd must stay inside verifier workspace", None)
        try:
            completed = subprocess.run(
                command,
                cwd=cwd,
                capture_output=True,
                text=True,
                timeout=timeout,
                shell=False,
            )
        except FileNotFoundError:
            return _receipt(criterion, VerifierStatus.SKIPPED, f"command executable not found: {command[0]}", None)
        except subprocess.TimeoutExpired as exc:
            output = _truncate_output((exc.stdout or "") + "\n" + (exc.stderr or ""))
            return _receipt(criterion, VerifierStatus.FAILED, f"command timed out after {timeout}s: {output}", None)

    output = _truncate_output((completed.stdout or "") + "\n" + (completed.stderr or ""))
    reason = f"command exited {completed.returncode}, expected {expected_exit}"
    if output.strip():
        reason = f"{reason}; output: {output}"
    status = VerifierStatus.PASSED if completed.returncode == expected_exit else VerifierStatus.FAILED
    return _receipt(criterion, status, reason, None)


def _command_is_allowed(command: list[str], criterion: CriterionArtifact) -> bool:
    configured = criterion.params.get("allowed_prefixes")
    prefixes = configured if isinstance(configured, list) and configured else DEFAULT_COMMAND_PREFIXES
    normalized = [_normalize_executable(command[0]), *[part.lower() for part in command[1:]]]
    for prefix in prefixes:
        if not isinstance(prefix, (list, tuple)) or not prefix:
            continue
        normalized_prefix = [_normalize_executable(str(prefix[0])), *[str(part).lower() for part in prefix[1:]]]
        if normalized[: len(normalized_prefix)] == normalized_prefix:
            return True
    return False


def _normalize_executable(token: str) -> str:
    name = Path(token).name.lower()
    return name[:-4] if name.endswith(".exe") else name


def _bounded_timeout(value) -> int:
    try:
        timeout = int(value)
    except (TypeError, ValueError):
        timeout = 20
    return max(1, min(timeout, MAX_COMMAND_TIMEOUT_SECONDS))


def _materialize_artifacts(workspace: Path, artifacts: dict[str, Artifact]) -> None:
    for artifact in artifacts.values():
        relative = _safe_relative_path(artifact.path_or_name)
        if relative is None:
            continue
        target = workspace.joinpath(*relative.parts)
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(artifact.text, encoding="utf-8")


def _safe_relative_path(path_or_name: str) -> PurePosixPath | None:
    normalized = path_or_name.replace("\\", "/")
    path = PurePosixPath(normalized)
    if path.is_absolute() or ".." in path.parts or not path.parts:
        return None
    return path


def _resolve_safe_cwd(workspace: Path, cwd_value: str) -> Path | None:
    if cwd_value in {"", "."}:
        return workspace.resolve()
    relative = _safe_relative_path(cwd_value)
    if relative is None:
        return None
    cwd = workspace.joinpath(*relative.parts).resolve()
    workspace_resolved = workspace.resolve()
    try:
        cwd.relative_to(workspace_resolved)
    except ValueError:
        return None
    cwd.mkdir(parents=True, exist_ok=True)
    return cwd


def _truncate_output(text: str) -> str:
    text = text.strip()
    if len(text) <= MAX_COMMAND_OUTPUT_CHARS:
        return text
    return text[:MAX_COMMAND_OUTPUT_CHARS] + "\n[truncated command verifier output]"


def _receipt(
    criterion: CriterionArtifact,
    status: VerifierStatus,
    reason: str,
    artifact: Artifact | None,
) -> VerifierReceipt:
    payload = {
        "criterion": criterion.criterion_id,
        "status": status.value,
        "reason": reason,
        "artifact": artifact.artifact_id if artifact else None,
    }
    return VerifierReceipt(
        receipt_id=stable_id("verifier", payload),
        criterion_id=criterion.criterion_id,
        status=status,
        reason=reason,
        artifact_id=artifact.artifact_id if artifact else None,
        evidence_refs=[artifact.blob_ref] if artifact else [],
    )
